1	import {
2	  DUEL_BUTTONS,
3	  DUEL_INPUT,
4	  movesetVersion,
5	  strikesWithHitbox,
6	  THROW_CHORD_PARTNER,
7	  type CancelCommand,
8	  type DuelMove,
9	  type DuelMoveset,
10	  type GuardLevel,
11	} from "@pirate-sea-race/content/moves";
12	import { clampInt, divTrunc } from "../fixed.js";
13	import { overlaps, worldBox, type Facing, type WorldBox } from "./boxes.js";
14	import {
15	  atWall,
16	  boltDirection,
17	  firstMeeting,
18	  firstReach,
19	  insideZone,
20	  laidZone,
21	  pathX,
22	  projectileOf,
23	  releasedBolt,
24	  substeps,
25	  type BoltPath,
26	} from "./entities.js";
27	import { directions, sanitizeDuelInput, type DuelInputs } from "./input.js";
28	import {
29	  canAct,
30	  currentMoveFrame,
31	  findMove,
32	  kitOf,
33	  moveDuration,
34	  type Bolt,
35	  type DuelConfig,
36	  type DuelEvent,
37	  type DuelResult,
38	  type DuelState,
39	  type FighterState,
40	  type InputBuffer,
41	  type PlayerIndex,
42	  type Stance,
43	  type Zone,
44	} from "./state.js";
45	
46	/** One player's input for this frame, read against last frame's held buttons. */
47	interface FrameInput {
48	  readonly bits: number;
49	  readonly h: -1 | 0 | 1;
50	  readonly v: -1 | 0 | 1;
51	  readonly buffer: InputBuffer;
52	}
53	
54	/** What a contact deals: a strike's or throw's own fields, or a bolt's (its projectile data). */
55	interface Strike {
56	  /** The move or projectile id events name. */
57	  readonly id: string;
58	  readonly damage: number;
59	  readonly hitstun: number;
60	  readonly blockstun: number;
61	  readonly hitPushback: number;
62	  readonly blockPushback: number;
63	  readonly launch: number;
64	  readonly guardStaminaCost: number;
65	}
66	
67	/** What one fighter's move or bolt does to the other this frame, detected against the start-of-frame state. */
68	interface Contact {
69	  readonly kind: "hit" | "block" | "grab";
70	  readonly strike: Strike;
71	  /** The defender's stance at contact. */
72	  readonly stance: Stance;
73	  /**
74	   * For a bolt's contact, the way the bolt flies: the defender is pushed that way, and the owner is neither moved nor
75	   * marked as having hit. Null for the fighter's own move.
76	   */
77	  readonly bolt: Facing | null;
78	}
79	
80	function strikeOf(move: DuelMove): Strike {
81	  const { damage, hitstun, blockstun, hitPushback, blockPushback, launch, guardStaminaCost } = move;
82	  return { id: move.timing.id, damage, hitstun, blockstun, hitPushback, blockPushback, launch, guardStaminaCost };
83	}
84	
85	type Pair<T> = readonly [T, T];
86	
87	const OTHER = [1, 0] as const;
88	
89	/** One value per fighter, player one's first. */
90	function both<T>(each: (index: PlayerIndex) => T): Pair<T> {
91	  return [each(0), each(1)];
92	}
93	
94	/**
95	 * Advances the duel by one 60 Hz frame (order of operations in docs/duel.md):
96	 *
97	 * 1. read both inputs (opposite directions cancel; newly pressed buttons enter the 4-frame buffer);
98	 * 2. detect every hit, block and grab of the frame against the start-of-frame state of both fighters, and sweep both
99	 *    bolts (one released this frame included) against each other and the opposing hurtbox;
100	 * 3. settle same-frame interactions (throw against throw breaks both; a strike or bolt that hits or is blocked beats a
101	 *    throw; the opponent's own move takes priority over its bolt; two bolts that meet destroy each other);
102	 * 4. apply all results together, damage and stamina from start-of-frame values; fighters not struck advance their
103	 *    action (a light or heavy may still become the throw inside the chord window, a feint may be cancelled into a
104	 *    normal) or start a new one from their input;
105	 * 5. move, apply gravity, keep fighters inside the walls and apart; move bolts, age bolts and smoke screens;
106	 * 6. regenerate stamina, mark the fighters inside a smoke screen, then decide KO, timeout and overtime from both
107	 *    fighters' health.
108	 *
109	 * Neither fighter is processed "first": every decision for one fighter reads only the start-of-frame state and the
110	 * frame's inputs. The input state is never mutated. A finished duel only advances its frame counter.
111	 */
112	export function stepDuel(config: DuelConfig, state: DuelState, inputs: DuelInputs): DuelState {
113	  const { moveset } = config;
114	  const version = movesetVersion(moveset);
115	  if (state.movesetVersion !== version) {
116	    throw new Error(`the duel runs on moveset ${state.movesetVersion}, not ${version}`);
117	  }
118	  const frame = state.frame + 1;
119	  if (state.result !== null) return { ...state, frame, events: [] };
120	
121	  const fighters = state.fighters;
122	  const input: Pair<FrameInput> = [readInput(moveset, fighters[0], inputs[0]), readInput(moveset, fighters[1], inputs[1])];
123	
124	  // 2. Detection, each against the same start-of-frame state.
125	  let contacts: Pair<Contact | null> = [detect(moveset, fighters, 0, input), detect(moveset, fighters, 1, input)];
126	  const bolts = sweepBolts(moveset, fighters, input);
127	
128	  // 3. Same-frame interactions.
129	  const clash = contacts[0]?.kind === "grab" && contacts[1]?.kind === "grab";
130	  if (clash) {
131	    contacts = [null, null];
132	  } else {
133	    // A grab fails against a strike or bolt that hits or is blocked on the same frame; an active hitbox that misses
134	    // does not stop it.
135	    const strikes = (contact: Contact | null) => contact !== null && contact.kind !== "grab";
136	    contacts = [
137	      contacts[0]?.kind === "grab" && (strikes(contacts[1]) || bolts.contacts[1] !== null) ? null : contacts[0],
138	      contacts[1]?.kind === "grab" && (strikes(contacts[0]) || bolts.contacts[0] !== null) ? null : contacts[1],
139	    ];
140	  }
141	  const escape: Pair<boolean> = [escapes(fighters[0], input[0]), escapes(fighters[1], input[1])];
142	  const throwBreak = clash || escape[0] || escape[1];
143	  // A bolt's contact applies unless the opponent's own move connects on the same frame, which takes priority and spends
144	  // the bolt; on a throw break nothing applies, and the bolt flies on.
145	  const boltSpent: Pair<boolean> = both((index) => bolts.clash || (bolts.contacts[index] !== null && !throwBreak));
146	  if (!throwBreak) contacts = both((index) => contacts[index] ?? bolts.contacts[index]);
147	
148	  // Displacement from pushback and throw breaks, from start-of-frame positions.
149	  const shift = [0, 0];
150	  const minX = moveset.fighter.pushbox.halfWidth;
151	  const maxX = moveset.arena.width - minX;
152	  for (const attacker of [0, 1] as const) {
153	    const contact = contacts[attacker];
154	    if (contact === null || contact.kind === "grab") continue;
155	    const defender = OTHER[attacker];
156	    const def = fighters[defender];
157	    const push = contact.kind === "hit" ? contact.strike.hitPushback : contact.strike.blockPushback;
158	    const direction = contact.bolt ?? awayFrom(def, fighters[attacker]);
159	    const target = clampInt(def.x + direction * push, minX, maxX);
160	    shift[defender]! += target - def.x;
161	    // Against a wall, the rest of a strike's pushback moves the attacker back instead; a bolt never moves its owner.
162	    if (contact.bolt === null) shift[attacker]! -= direction * (push - Math.abs(target - def.x));
163	  }
164	  if (throwBreak) {
165	    for (const index of [0, 1] as const) {
166	      shift[index]! += awayFrom(fighters[index], fighters[OTHER[index]]) * moveset.fighter.throwBreakPushback;
167	    }
168	  }
169	
170	  // 4. Apply results and advance actions.
171	  const events: DuelEvent[] = [];
172	  const spent = [false, false];
173	  const next = both((index): FighterState => {
174	    const self = fighters[index];
175	    const opponent = fighters[OTHER[index]];
176	    const incoming = contacts[OTHER[index]];
177	    const outgoing = contacts[index];
178	    const own = input[index];
179	    let fighter: FighterState = { ...self, held: own.bits, buffer: own.buffer };
180	    if (throwBreak) {
181	      // Two throws on one frame, or an escape: both fighters recover apart with no damage.
182	      if (clash) events.push({ kind: "throw-clash", attacker: index, moveId: self.moveId ?? "", damage: 0 });
183	      if (escape[OTHER[index]]) events.push({ kind: "throw-escape", attacker: index, moveId: moveset.commands.throw, damage: 0 });
184	      return startTimed(fighter, "throw-break", moveset.fighter.throwBreakFrames);
185	    }
186	    if (incoming !== null) {
187	      const attacker = OTHER[index];
188	      const result = react(moveset, fighter, incoming, attacker);
189	      events.push(result.event);
190	      if (incoming.kind === "block") spent[index] = true;
191	      return result.fighter;
192	    }
193	    if (outgoing !== null && outgoing.bolt === null) fighter = { ...fighter, moveHit: true };
194	    if (fighter.action === "thrown") {
195	      if (fighter.timer > 0) return { ...fighter, timer: fighter.timer - 1, actionFrame: fighter.actionFrame + 1 };
196	      // The escape window ran out: the throw lands.
197	      const move = findMove(moveset, moveset.commands.throw);
198	      const damage = scaledDamage(moveset, move.damage, fighter.combo);
199	      events.push({ kind: "throw", attacker: OTHER[index], moveId: move.timing.id, damage });
200	      return {
201	        ...startTimed(fighter, "knockdown", move.hitstun),
202	        health: Math.max(0, fighter.health - damage),
203	        combo: fighter.combo + 1,
204	      };
205	    }
206	    if (!canAct(self)) return chordThrow(moveset, fighter) ?? cancelFeint(moveset, fighter, opponent, own) ?? progress(moveset, fighter);
207	    const started = choose(moveset, fighter, opponent, own);
208	    if (started.action === "dash" || started.action === "backdash") spent[index] = true;
209	    return started;
210	  });
211	
212	  // 5. Movement: velocities, gravity and landing, walls, then pushboxes; then the bolts and smoke screens.
213	  const moved = both((index) => move(moveset, next[index], shift[index]!));
214	  const separated = separate(moveset, fighters, moved);
215	  const zones = both((index) => nextZone(moveset, fighters[index]));
216	  const flown = both((index) => nextBolt(moveset, bolts.paths[index], boltSpent[index]));
217	
218	  // 6. Stamina regeneration, smoke screen marks, then the result.
219	  const rules = moveset.rules;
220	  const final = both((index): FighterState => {
221	    const fighter = { ...separated[index], bolt: flown[index], zone: zones[index] };
222	    const marked = { ...fighter, obscured: insideZone(moveset, fighter, zones) };
223	    if (spent[index]) return { ...marked, staminaIdle: 0 };
224	    const idle = fighter.staminaIdle + 1;
225	    const regenerates =
226	      idle > rules.staminaRegenDelayFrames && (idle - rules.staminaRegenDelayFrames) % rules.staminaRegenIntervalFrames === 0;
227	    return { ...marked, staminaIdle: idle, stamina: regenerates ? Math.min(rules.maxStamina, fighter.stamina + 1) : fighter.stamina };
228	  });
229	
230	  const result = decide(moveset, state, frame, final);
231	  return {
232	    ...state,
233	    frame,
234	    phase: result === null ? (state.phase === "round" && frame >= rules.roundFrames ? "overtime" : state.phase) : "over",
235	    fighters: final,
236	    events,
237	    result,
238	  };
239	}
240	
241	function readInput(moveset: DuelMoveset, fighter: FighterState, raw: number): FrameInput {
242	  const bits = sanitizeDuelInput(raw);
243	  const pressed = bits & ~fighter.held;
244	  const buffer = Object.fromEntries(
245	    DUEL_BUTTONS.map((button) => [
246	      button,
247	      (pressed & DUEL_INPUT[button]) !== 0 ? moveset.rules.inputBufferFrames : Math.max(0, fighter.buffer[button] - 1),
248	    ]),
249	  ) as unknown as InputBuffer;
250	  return { bits, ...directions(bits), buffer };
251	}
252	
253	/** -1 or 1: the direction pointing from `other` to `self` (behind `self`'s facing when they share an x). */
254	function awayFrom(self: FighterState, other: FighterState): Facing {
255	  return self.x > other.x ? 1 : self.x < other.x ? -1 : self.facing === 1 ? -1 : 1;
256	}
257	
258	function isActiveFrame(move: DuelMove, moveFrame: number): boolean {
259	  return moveFrame > move.timing.startup && moveFrame <= move.timing.startup + move.timing.active;
260	}
261	
262	function isAirborne(fighter: FighterState): boolean {
263	  return fighter.y > 0 || fighter.vy > 0 || fighter.action === "jump";
264	}
265	
266	/** A free or blocking fighter changes stance with this frame's input; anyone else keeps the one they had. */
267	function stanceOf(fighter: FighterState, input: FrameInput): Stance {
268	  if (isAirborne(fighter)) return "airborne";
269	  if (canAct(fighter) || fighter.action === "blockstun") return input.v === -1 ? "crouching" : "standing";
270	  return fighter.crouching ? "crouching" : "standing";
271	}
272	
273	function detect(moveset: DuelMoveset, fighters: Pair<FighterState>, attacker: PlayerIndex, input: Pair<FrameInput>): Contact | null {
274	  const att = fighters[attacker];
275	  if (att.action !== "attack" || att.moveId === null || att.moveHit) return null;
276	  const move = findMove(moveset, att.moveId);
277	  if (!strikesWithHitbox(move) || !isActiveFrame(move, currentMoveFrame(att))) return null;
278	  const defender = OTHER[attacker];
279	  const def = fighters[defender];
280	  const stance = stanceOf(def, input[defender]);
281	  const reaches = () =>
282	    overlaps(worldBox(move.hitbox, att.x, att.y, att.facing), worldBox(moveset.fighter.hurtboxes[stance], def.x, def.y, def.facing));
283	
284	  if (move.kind === "throw") {
285	    const throwable =
286	      stance !== "airborne" && !["hitstun", "blockstun", "thrown", "throw-break", "knockdown"].includes(def.action);
287	    return throwable && reaches() ? { kind: "grab", strike: strikeOf(move), stance, bolt: null } : null;
288	  }
289	  if (!strikable(moveset, def, stance, move.guard) || !reaches()) return null;
290	  const guarding = guards(def, stance, input[defender], move.guard, awayFrom(def, att));
291	  return { kind: guarding ? "block" : "hit", strike: strikeOf(move), stance, bolt: null };
292	}
293	
294	/**
295	 * Whether a strike (or a bolt) of guard level `guard` can touch the defender at all: knocked-down and held fighters,
296	 * and a fighter in its move's strike-invulnerable frames, cannot be struck; crouching avoids highs whether or not it
297	 * guards.
298	 */
299	function strikable(moveset: DuelMoveset, def: FighterState, stance: Stance, guard: GuardLevel): boolean {
300	  if (def.action === "thrown" || def.action === "knockdown") return false;
301	  if (def.action === "attack" && def.moveId !== null && findMove(moveset, def.moveId).strikeInvulnerable >= currentMoveFrame(def)) {
302	    return false;
303	  }
304	  return !(guard === "high" && stance === "crouching");
305	}
306	
307	/**
308	 * Whether the defender guards: it can act (or is in blockstun), is grounded, holds `away` (away from the attacker,
309	 * or the way a bolt flies), and its stance blocks the level: standing blocks highs and mids, crouching blocks lows.
310	 */
311	function guards(def: FighterState, stance: Stance, input: FrameInput, guard: GuardLevel, away: Facing): boolean {
312	  return (
313	    stance !== "airborne" &&
314	    (canAct(def) || def.action === "blockstun") &&
315	    input.h === away &&
316	    (stance === "standing" ? guard === "high" || guard === "mid" : guard === "low")
317	  );
318	}
319	
320	/** Both fighters' bolts this frame: their paths, their contacts (by owner), and whether they destroyed each other. */
321	interface BoltSweep {
322	  readonly paths: Pair<BoltPath | null>;
323	  readonly contacts: Pair<Contact | null>;
324	  readonly clash: boolean;
325	}
326	
327	/**
328	 * Sweeps both bolts along this frame's movement in substeps, moved in step: a bolt already flying moves its speed, one
329	 * released this frame is tested where it appears. Each bolt's first overlap with the opposing hurtbox (start-of-frame,
330	 * as for strikes) and the two bolts' first overlap are compared: bolts that meet no later than either one reaches a
331	 * fighter destroy each other; otherwise every bolt that reaches its target contacts it. Nothing depends on the slot.
332	 */
333	function sweepBolts(moveset: DuelMoveset, fighters: Pair<FighterState>, input: Pair<FrameInput>): BoltSweep {
334	  const paths = both((index): BoltPath | null => {
335	    const owner = fighters[index];
336	    const { bolt } = owner;
337	    if (bolt !== null) return bolt.life > 1 ? { bolt: { ...bolt, life: bolt.life - 1 }, from: bolt.x, travel: bolt.vx } : null;
338	    const released = releasedBolt(moveset, owner);
339	    return released === null ? null : { bolt: released, from: released.x, travel: 0 };
340	  });
341	  const count = substeps(moveset, paths);
342	  const reach = both((owner): { at: number; contact: Contact } | null => {
343	    const path = paths[owner];
344	    if (path === null) return null;
345	    const defender = OTHER[owner];
346	    const def = fighters[defender];
347	    const stance = stanceOf(def, input[defender]);
348	    const projectile = projectileOf(moveset, path.bolt);
349	    if (!strikable(moveset, def, stance, projectile.guard)) return null;
350	    const target: WorldBox = worldBox(moveset.fighter.hurtboxes[stance], def.x, def.y, def.facing);
351	    const at = firstReach(moveset, path, count, target);
352	    if (at === null) return null;
353	    const direction = boltDirection(path.bolt);
354	    const guarding = guards(def, stance, input[defender], projectile.guard, direction);
355	    const { id, damage, hitstun, blockstun, hitPushback, blockPushback, guardStaminaCost } = projectile;
356	    const strike: Strike = { id, damage, hitstun, blockstun, hitPushback, blockPushback, launch: 0, guardStaminaCost };
357	    return { at, contact: { kind: guarding ? "block" : "hit", strike, stance, bolt: direction } };
358	  });
359	  const [a, b] = paths;
360	  const meeting = a !== null && b !== null ? firstMeeting(moveset, a, b, count) : null;
361	  const clash = meeting !== null && reach.every((entry) => entry === null || meeting <= entry.at);
362	  return { paths, contacts: both((index) => (clash ? null : (reach[index]?.contact ?? null))), clash };
363	}
364	
365	/**
366	 * A bolt after this frame: gone when spent (contact or clash) or at a wall, else moved (its path already ended the
367	 * life of a bolt on its last frame).
368	 */
369	function nextBolt(moveset: DuelMoveset, path: BoltPath | null, spent: boolean): Bolt | null {
370	  if (path === null || spent) return null;
371	  const x = pathX(path, 1, 1);
372	  return atWall(moveset, path.bolt, x) ? null : { ...path.bolt, x };
373	}
374	
375	/** A smoke screen after this frame: laid on the cast's first active frame, gone at the end of its life. */
376	function nextZone(moveset: DuelMoveset, fighter: FighterState): Zone | null {
377	  const { zone } = fighter;
378	  if (zone !== null) return zone.life > 1 ? { ...zone, life: zone.life - 1 } : null;
379	  return laidZone(moveset, fighter);
380	}
381	
382	/** A thrown fighter escapes by pressing light and heavy (both within the buffer) while the window is open. */
383	function escapes(fighter: FighterState, input: FrameInput): boolean {
384	  return fighter.action === "thrown" && fighter.timer > 0 && input.buffer.light > 0 && input.buffer.heavy > 0;
385	}
386	
387	function scaledDamage(moveset: DuelMoveset, damage: number, comboHits: number): number {
388	  const scaling = moveset.rules.comboScaling;
389	  const percent = scaling[Math.min(comboHits, scaling.length - 1)]!;
390	  return divTrunc(damage * percent, 100);
391	}
392	
393	/** Starts a timed action lasting `frames` frames, the current one included. */
394	function startTimed(fighter: FighterState, action: FighterState["action"], frames: number): FighterState {
395	  return {
396	    ...fighter,
397	    action,
398	    actionFrame: 1,
399	    timer: Math.max(0, frames - 1),
400	    moveId: null,
401	    moveHit: false,
402	    vx: 0,
403	    vy: fighter.y > 0 ? Math.min(fighter.vy, 0) : 0,
404	    crouching: false,
405	  };
406	}
407	
408	function react(moveset: DuelMoveset, fighter: FighterState, contact: Contact, attacker: PlayerIndex): { fighter: FighterState; event: DuelEvent } {
409	  const { strike, stance } = contact;
410	  const { rules } = moveset;
411	  const moveId = strike.id;
412	  const crouching = stance === "crouching";
413	  if (contact.kind === "grab") {
414	    // The escape window is the ten frames after the grab; presses from before it do not count.
415	    const held = startTimed(fighter, "thrown", rules.throwEscapeFrames + 1);
416	    return {
417	      fighter: { ...held, combo: 0, buffer: { ...held.buffer, light: 0, heavy: 0 } },
418	      event: { kind: "grab", attacker, moveId, damage: 0 },
419	    };
420	  }
421	  if (contact.kind === "block") {
422	    const cost = strike.guardStaminaCost;
423	    if (cost > fighter.stamina) {
424	      const staggered = startTimed(fighter, "stagger", rules.guardBreakStaggerFrames);
425	      return {
426	        fighter: { ...staggered, combo: 0, stamina: Math.min(rules.maxStamina, fighter.stamina + rules.guardBreakStaminaRestore) },
427	        event: { kind: "guard-break", attacker, moveId, damage: 0 },
428	      };
429	    }
430	    return {
431	      fighter: { ...startTimed(fighter, "blockstun", strike.blockstun), combo: 0, crouching, stamina: fighter.stamina - cost },
432	      event: { kind: "block", attacker, moveId, damage: 0 },
433	    };
434	  }
435	  // A fighter still in hitstun continues the combo; a free one starts a new one.
436	  const comboHits = fighter.action === "hitstun" && !canAct(fighter) ? fighter.combo : 0;
437	  const damage = scaledDamage(moveset, strike.damage, comboHits);
438	  const combo = comboHits + 1;
439	  const capped = combo >= rules.comboCap;
440	  const struck = startTimed(fighter, capped ? "knockdown" : "hitstun", capped ? rules.forcedRecoveryFrames : strike.hitstun);
441	  return {
442	    fighter: {
443	      ...struck,
444	      health: Math.max(0, fighter.health - damage),
445	      combo,
446	      crouching: capped ? false : crouching,
447	      vy: strike.launch > 0 ? strike.launch : struck.vy,
448	    },
449	    event: { kind: "hit", attacker, moveId, damage },
450	  };
451	}
452	
453	/** One more frame of an action the fighter cannot leave yet. */
454	function progress(moveset: DuelMoveset, fighter: FighterState): FighterState {
455	  const actionFrame = fighter.actionFrame + 1;
456	  const timer = Math.max(0, fighter.timer - 1);
457	  switch (fighter.action) {
458	    case "attack": {
459	      const move = findMove(moveset, fighter.moveId!);
460	      return { ...fighter, actionFrame, timer, vx: advance(move, actionFrame, fighter.facing) };
461	    }
462	    case "dash":
463	    case "backdash":
464	      return { ...fighter, actionFrame, timer };
465	    case "jump":
466	      return { ...fighter, actionFrame };
467	    default:
468	      return { ...fighter, actionFrame, timer, vx: 0 };
469	  }
470	}
471	
472	/**
473	 * The throw chord window (§8, keyboard rollover): a light or heavy move that a free fighter started becomes the throw
474	 * when the other button is pressed within `throwChordFrames` frames of the start, before the move's first active
475	 * frame. The throw keeps the frames already spent, so it lands as if both buttons had gone down together, and a lone
476	 * light or heavy keeps its own startup. `fighter` carries this frame's input buffer; null leaves the move as it is.
477	 */
478	function chordThrow(moveset: DuelMoveset, fighter: FighterState): FighterState | null {
479	  if (fighter.action !== "attack" || fighter.moveId === null || fighter.moveHit) return null;
480	  if (fighter.actionFrame > moveset.rules.throwChordFrames) return null;
481	  const { commands } = moveset;
482	  const command = (Object.keys(THROW_CHORD_PARTNER) as (keyof typeof THROW_CHORD_PARTNER)[]).find((name) => commands[name] === fighter.moveId);
483	  if (command === undefined || fighter.buffer[THROW_CHORD_PARTNER[command]] === 0) return null;
484	  if (fighter.actionFrame >= findMove(moveset, fighter.moveId).timing.startup) return null;
485	  const grab = findMove(moveset, commands.throw);
486	  const actionFrame = fighter.actionFrame + 1;
487	  return {
488	    ...fighter,
489	    moveId: grab.timing.id,
490	    actionFrame,
491	    timer: moveDuration(grab) - actionFrame,
492	    crouching: grab.stance === "crouching",
493	    vx: advance(grab, actionFrame, fighter.facing),
494	    buffer: { ...fighter.buffer, light: 0, heavy: 0 },
495	  };
496	}
497	
498	function advance(move: DuelMove, moveFrame: number, facing: Facing): number {
499	  return move.advance !== 0 && moveFrame <= move.timing.startup + move.timing.active ? move.advance * facing : 0;
500	}
501	
502	/** The way a fighter starting something faces: towards the opponent (§8's auto-facing). */
503	function facingTowards(self: FighterState, opponent: FighterState): Facing {
504	  return opponent.x > self.x ? 1 : opponent.x < self.x ? -1 : self.facing;
505	}
506	
507	/** Starts move `id` on its first frame, facing `facing`, with the buttons it used taken out of the buffer. */
508	function startAttack(moveset: DuelMoveset, self: FighterState, facing: Facing, id: string, used: InputBuffer): FighterState {
509	  const move = findMove(moveset, id);
510	  return {
511	    ...self,
512	    facing,
513	    combo: 0,
514	    moveHit: false,
515	    vy: 0,
516	    action: "attack",
517	    moveId: id,
518	    actionFrame: 1,
519	    timer: moveDuration(move) - 1,
520	    crouching: move.stance === "crouching",
521	    vx: advance(move, 1, facing),
522	    buffer: used,
523	  };
524	}
525	
526	function consume(buffer: InputBuffer, ...buttons: readonly (keyof InputBuffer)[]): InputBuffer {
527	  return { ...buffer, ...Object.fromEntries(buttons.map((button) => [button, 0])) } as InputBuffer;
528	}
529	
530	/**
531	 * The normal a buffered light or heavy asks for (§8): both are the throw; down + heavy the low sweep, forward + heavy
532	 * the launcher; down + light the anti-air. Null without either press.
533	 */
534	function normalCommand(input: FrameInput, facing: Facing): { command: CancelCommand; used: readonly (keyof InputBuffer)[] } | null {
535	  const { buffer, h, v } = input;
536	  if (buffer.light > 0 && buffer.heavy > 0) return { command: "throw", used: ["light", "heavy"] };
537	  if (buffer.heavy > 0) return { command: v === -1 ? "downHeavy" : h === facing ? "forwardHeavy" : "heavy", used: ["heavy"] };
538	  if (buffer.light > 0) return { command: v === -1 ? "downLight" : "light", used: ["light"] };
539	  return null;
540	}
541	
542	/** A special whose entity (bolt or smoke screen) is still out cannot start again: at most one of each per fighter. */
543	function specialReady(moveset: DuelMoveset, self: FighterState, id: string): boolean {
544	  const move = findMove(moveset, id);
545	  return !(move.projectile !== undefined && self.bolt !== null) && !(move.zone !== undefined && self.zone !== null);
546	}
547	
548	/**
549	 * A feint's cancel: from the move frame its `cancel` opens (after the readable reappearance), a buffered normal it
550	 * lists replaces the rest of the feint, as if started by a free fighter. Specials, the feint included, never cancel it.
551	 * Null leaves the feint running.
552	 */
553	function cancelFeint(moveset: DuelMoveset, fighter: FighterState, opponent: FighterState, input: FrameInput): FighterState | null {
554	  if (fighter.action !== "attack" || fighter.moveId === null) return null;
555	  const { cancel } = findMove(moveset, fighter.moveId);
556	  if (cancel === undefined || currentMoveFrame(fighter) < cancel.opens) return null;
557	  const facing = facingTowards(fighter, opponent);
558	  const normal = normalCommand(input, facing);
559	  if (normal === null || !cancel.into.includes(normal.command)) return null;
560	  return startAttack(moveset, fighter, facing, moveset.commands[normal.command], consume(fighter.buffer, ...normal.used));
561	}
562	
563	/** A free fighter turns to face the opponent and starts whatever its input asks for (§8's priorities). */
564	function choose(moveset: DuelMoveset, self: FighterState, opponent: FighterState, input: FrameInput): FighterState {
565	  const facing = facingTowards(self, opponent);
566	  const { buffer, h, v } = input;
567	  const { commands, fighter: body, rules } = moveset;
568	  const kit = kitOf(moveset, self);
569	  const base: FighterState = { ...self, facing, combo: 0, moveHit: false, moveId: null, crouching: false, vy: 0 };
570	  const attack = (id: string, used: InputBuffer): FighterState => startAttack(moveset, base, facing, id, used);
571	  const forward = h === facing;
572	  const back = h === -facing;
573	
574	  if (buffer.light > 0 && buffer.heavy > 0) return attack(commands.throw, consume(buffer, "light", "heavy"));
575	  if (buffer.special1 > 0 && specialReady(moveset, self, kit.special1)) return attack(kit.special1, consume(buffer, "special1"));
576	  if (buffer.special2 > 0 && specialReady(moveset, self, kit.special2)) return attack(kit.special2, consume(buffer, "special2"));
577	  if (buffer.heavy > 0) {
578	    return attack(v === -1 ? commands.downHeavy : forward ? commands.forwardHeavy : commands.heavy, consume(buffer, "heavy"));
579	  }
580	  if (buffer.light > 0) return attack(v === -1 ? commands.downLight : commands.light, consume(buffer, "light"));
581	  if (buffer.dash > 0 && self.stamina >= rules.dashStaminaCost) {
582	    const frames = back ? body.backdashFrames : body.dashFrames;
583	    return {
584	      ...base,
585	      action: back ? "backdash" : "dash",
586	      actionFrame: 1,
587	      timer: frames - 1,
588	      vx: back ? -facing * body.backdashSpeed : facing * body.dashSpeed,
589	      stamina: self.stamina - rules.dashStaminaCost,
590	      buffer: consume(buffer, "dash"),
591	    };
592	  }
593	  /** A free action: its frame count carries on while the fighter keeps doing it. */
594	  const free = (action: "idle" | "walk" | "crouch" | "jump", vx: number): FighterState => ({
595	    ...base,
596	    action,
597	    actionFrame: self.action === action ? self.actionFrame + 1 : 1,
598	    timer: 0,
599	    vx,
600	  });
601	  if (v === 1) return { ...free("jump", h * body.jumpSpeedX), vy: body.jumpVelocity };
602	  if (v === -1) return { ...free("crouch", 0), crouching: true };
603	  if (h !== 0) return free("walk", forward ? facing * body.walkForwardSpeed : -facing * body.walkBackSpeed);
604	  return free("idle", 0);
605	}
606	
607	/** Velocity, gravity and landing for one fighter, plus this frame's pushback, kept inside the walls. */
608	function move(moveset: DuelMoveset, fighter: FighterState, shift: number): FighterState {
609	  const minX = moveset.fighter.pushbox.halfWidth;
610	  const maxX = moveset.arena.width - minX;
611	  const x = clampInt(fighter.x + shift + fighter.vx, minX, maxX);
612	  if (fighter.y === 0 && fighter.vy <= 0) return { ...fighter, x, vy: 0 };
613	  const y = fighter.y + fighter.vy;
614	  if (y > 0) return { ...fighter, x, y, vy: fighter.vy - moveset.fighter.gravity };
615	  const landed = { ...fighter, x, y: 0, vx: 0, vy: 0 };
616	  return fighter.action === "jump" ? { ...landed, action: "idle", actionFrame: 1 } : landed;
617	}
618	
619	/**
620	 * Pushes overlapping pushboxes apart, each fighter by half the overlap rounded up, so neither side is favoured; a
621	 * fighter against a wall passes its share to the other. `before` is the start-of-frame state, for ties.
622	 */
623	function separate(moveset: DuelMoveset, before: Pair<FighterState>, fighters: Pair<FighterState>): Pair<FighterState> {
624	  const { halfWidth, height } = moveset.fighter.pushbox;
625	  const [a, b] = fighters;
626	  const dx = Math.abs(a.x - b.x);
627	  if (dx >= 2 * halfWidth || a.y >= b.y + height || b.y >= a.y + height) return fighters;
628	  const aLeft = leftFirst(a, b, before[0], before[1]);
629	  if (aLeft === null) return fighters;
630	  const [left, right] = aLeft ? [a, b] : [b, a];
631	  const half = divTrunc(2 * halfWidth - dx + 1, 2);
632	  const minX = halfWidth;
633	  const maxX = moveset.arena.width - halfWidth;
634	  let leftX = left.x - half;
635	  let rightX = right.x + half;
636	  if (leftX < minX) {
637	    rightX += minX - leftX;
638	    leftX = minX;
639	  }
640	  if (rightX > maxX) {
641	    leftX = Math.max(minX, leftX - (rightX - maxX));
642	    rightX = maxX;
643	  }
644	  const placedLeft = { ...left, x: leftX };
645	  const placedRight = { ...right, x: rightX };
646	  return aLeft ? [placedLeft, placedRight] : [placedRight, placedLeft];
647	}
648	
649	/**
650	 * Whether fighter `a` ends up on the left of `b`: by x, then by start-of-frame x (fighters never pass through each
651	 * other), then by velocity, then by facing (the one facing right is on the left). Every key flips when the arena is
652	 * mirrored, so the answer never depends on the slot; a tie on all of them is `null`, and the two stay where they are.
653	 */
654	function leftFirst(a: FighterState, b: FighterState, a0: FighterState, b0: FighterState): boolean | null {
655	  if (a.x !== b.x) return a.x < b.x;
656	  if (a0.x !== b0.x) return a0.x < b0.x;
657	  if (a.vx !== b.vx) return a.vx < b.vx;
658	  if (a.facing !== b.facing) return a.facing === 1;
659	  return null;
660	}
661	
662	/** KO first (both at once is a draw), then the clock: timeout, overtime, draw (§7). */
663	function decide(moveset: DuelMoveset, state: DuelState, frame: number, fighters: Pair<FighterState>): DuelResult | null {
664	  const [a, b] = fighters;
665	  if (a.health === 0 && b.health === 0) return { winner: null, reason: "double-ko", frame };
666	  if (a.health === 0 || b.health === 0) return { winner: a.health === 0 ? 1 : 0, reason: "ko", frame };
667	  const { roundFrames, overtimeFrames } = moveset.rules;
668	  const compare = (reason: DuelResult["reason"]): DuelResult | null =>
669	    a.health === b.health ? (reason === "timeout" ? null : { winner: null, reason, frame }) : { winner: a.health > b.health ? 0 : 1, reason, frame };
670	  if (state.phase === "round" && frame >= roundFrames) return compare("timeout");
671	  if (state.phase === "overtime" && frame >= roundFrames + overtimeFrames) return compare("overtime");
672	  return null;
673	}
674

