2	import type { Facing } from "./boxes.js";
3	
4	/** Static duel data the step reads; it never changes during a duel. */
5	export interface DuelConfig {
6	  readonly moveset: DuelMoveset;
7	}
8	
9	export const defaultDuelConfig: DuelConfig = { moveset: duelistMoveset };
10	
11	/**
12	 * What a fighter is doing. `idle`, `walk` and `crouch` are free: the fighter can start anything on the next frame.
13	 * `jump` lasts until landing. The others are timed by `timer`.
14	 */
15	export type FighterAction =
16	  | "idle"
17	  | "walk"
18	  | "crouch"
19	  | "jump"
20	  | "dash"
21	  | "backdash"
22	  | "attack"
23	  | "hitstun"
24	  | "blockstun"
25	  | "stagger"
26	  | "thrown"
27	  | "throw-break"
28	  | "knockdown";
29	
30	export type Stance = "standing" | "crouching" | "airborne";
31	
32	/** Frames each button press stays usable (0 = no press waiting). */
33	export type InputBuffer = Readonly<Record<DuelButton, number>>;
34	
35	/**
36	 * A fighter's flying bolt (a `projectile` special's entity). At most one per fighter: the cast cannot start while it
37	 * flies. Its strike data is `moveId`'s `projectile`.
38	 */
39	export interface Bolt {
40	  /** The cast move that released it, one of its owner's kit specials. */
41	  readonly moveId: string;
42	  /** Position in sub-pixels; the bolt's box is placed here, facing the way it flies. */
43	  readonly x: number;
44	  readonly y: number;
45	  /** Sub-pixels per frame: plus or minus the projectile's speed. */
46	  readonly vx: number;
47	  /** Frames it still exists after the current one. */
48	  readonly life: number;
49	}
50	
51	/**
52	 * A fighter's smoke screen (a `zone` special's entity). At most one per fighter: the cast cannot start while it lasts.
53	 * It never strikes; it marks the fighters inside it (`FighterState.obscured`).
54	 */
55	export interface Zone {
56	  /** The cast move that laid it, one of its owner's kit specials. */
57	  readonly moveId: string;
58	  /** The caster's origin and facing at the cast; the zone's box is placed there. */
59	  readonly x: number;
60	  readonly facing: Facing;
61	  /** Frames it still exists after the current one. */
62	  readonly life: number;
63	}
64	
65	/**
66	 * One fighter. Every number is an integer: positions in sub-pixels (x from the left wall, y up from the floor, the
67	 * origin in the middle of the feet), velocities in sub-pixels per frame, durations in frames.
68	 */
69	export interface FighterState {
70	  readonly x: number;
71	  readonly y: number;
72	  readonly vx: number;
73	  readonly vy: number;
74	  readonly facing: Facing;
75	  readonly health: number;
76	  readonly stamina: number;
77	  /** Frames since stamina was last spent or a block was taken. */
78	  readonly staminaIdle: number;
79	  readonly action: FighterAction;
80	  /** Frames spent in the current action, counting the frame that started it. For an attack, the move's frame. */
81	  readonly actionFrame: number;
82	  /** Frames of the current timed action still to come; the fighter is free on the frame after it reaches 0. */
83	  readonly timer: number;
84	  /** The move being performed, while `action` is `attack`. */
85	  readonly moveId: string | null;
