1	import { z } from "zod";
2	import { baselineFrameBudgets, moveTimingSchema, type MoveTiming } from "../frameBudgets.js";
3	import { formatIssues, type ValidationResult } from "../rules.js";
4	
5	/**
6	 * An axis-aligned box in integer sub-pixels, relative to a fighter's origin (the middle of its feet) for a fighter
7	 * facing right; y grows upwards from the floor. The box covers the half-open ranges [x, x + w) × [y, y + h), so it
8	 * needs a positive width and height to cover anything.
9	 */
10	export const boxSchema = z.strictObject({
11	  x: z.int(),
12	  y: z.int(),
13	  w: z.int().positive(),
14	  h: z.int().positive(),
15	});
16	
17	export type Box = z.infer<typeof boxSchema>;
18	
19	const count = z.int().nonnegative();
20	const positive = z.int().positive();
21	
22	/**
23	 * §8's move timing, restricted to what a fighter's own move can be: numeric active frames, and a frame advantage on
24	 * block, unguardable (a throw) or spacing-dependent (a move that never strikes with its own hitbox, such as a
25	 * projectile cast: what it leaves depends on its entity). The rows go through §8's own schema, so its rules (positive
26	 * startup and active frames, block advantage within active + recovery) are checked in one place.
27	 */
28	export const duelMoveTimingSchema = moveTimingSchema.transform((timing, ctx) => {
29	  const { active } = timing;
30	  if (active === "projectile-life") {
31	    ctx.issues.push({ code: "custom", input: active, path: ["active"], message: "a fighter's move needs a number of active frames" });
32	    return z.NEVER;
33	  }
34	  return { ...timing, active };
35	});
36	
37	export type DuelMoveTiming = z.infer<typeof duelMoveTimingSchema>;
38	
39	export const guardLevelSchema = z.enum(["high", "mid", "low", "unguardable"]);
40	export type GuardLevel = z.infer<typeof guardLevelSchema>;
41	
42	export const moveCategorySchema = z.enum(["light", "heavy", "special", "throw"]);
43	export type MoveCategory = z.infer<typeof moveCategorySchema>;
44	
45	/**
46	 * What a move does on its active frames. `strike` moves (throws included) connect with their own hitbox; the others
47	 * never do: a `projectile` move releases its bolt, a `zone` move lays its zone, and a `feint` only moves its fighter.
48	 * `strikesWithHitbox` is the one rule for which moves strike.
49	 */
50	export const moveEffectSchema = z.enum(["strike", "projectile", "zone", "feint"]);
51	export type MoveEffect = z.infer<typeof moveEffectSchema>;
52	
53	/** The guard levels a strike can have; only a throw is unguardable. */
54	const strikeGuardSchema = z.enum(["high", "mid", "low"]);
55	
56	/**
57	 * The bolt a `projectile` move releases on its first active frame. It flies straight at `speed`, strikes once like a
58	 * strike of the fighter's own (the same guard, stun, pushback and stamina rules), and dies on contact, at a wall or
59	 * after `life` frames. `id` names it in events; it is never a fighter's move.
60	 */
61	export const duelProjectileSchema = z.strictObject({
62	  id: z.string().regex(/^[a-z][a-z0-9-]*$/),
63	  name: z.string().min(1),
64	  /** Where the bolt appears, relative to the caster's origin for a caster facing right. */
65	  spawn: z.strictObject({ x: z.int(), y: z.int().nonnegative() }),
66	  /** Relative to the bolt's position, for a bolt flying right. */
67	  box: boxSchema,
68	  /** Sub-pixels per frame. */
69	  speed: z.int().positive(),
70	  /** Frames the bolt exists, the one it appears on included. */
71	  life: z.int().positive(),
72	  guard: strikeGuardSchema,
73	  damage: z.int().positive(),
74	  hitstun: z.int().positive(),
75	  blockstun: z.int().positive(),
76	  hitPushback: z.int().nonnegative(),
77	  blockPushback: z.int().nonnegative(),
78	  guardStaminaCost: z.int().nonnegative(),
79	});
80	
81	export type DuelProjectile = z.infer<typeof duelProjectileSchema>;
82	
83	/**
84	 * The timed zone a `zone` move lays on its first active frame, where the caster stands. It never strikes; it marks
85	 * the fighters whose hurtbox is inside it (the renderer obscures their startups, never their position or health).
86	 */
87	export const duelZoneSchema = z.strictObject({
88	  /** Relative to the caster's origin at the cast, for a caster facing right. */
89	  box: boxSchema,
90	  /** Frames the zone exists, the one it appears on included. */
91	  life: z.int().positive(),
92	});
93	
94	export type DuelZone = z.infer<typeof duelZoneSchema>;
95	
96	/** The normal commands a move can be cancelled into (never a special). */
97	export const cancelCommandSchema = z.enum(["light", "downLight", "heavy", "downHeavy", "forwardHeavy", "throw"]);
98	export type CancelCommand = z.infer<typeof cancelCommandSchema>;
99	
100	/**
101	 * A feint's cancel: from move frame `opens` on, a buffered normal in `into` replaces the rest of the move. It opens
102	 * only after the feint's readable reappearance (`FEINT_REAPPEARANCE_FRAMES` of recovery).
103	 */
104	export const duelCancelSchema = z.strictObject({
105	  opens: z.int().positive(),
106	  into: z.array(cancelCommandSchema).min(1).readonly(),
107	});
108	
109	export type DuelCancel = z.infer<typeof duelCancelSchema>;
110	
111	/**
112	 * Recovery frames at the end of every feint dash that nothing can cancel and no invulnerability covers: Smoke's
113	 * readable reappearance (§9).
114	 */
115	export const FEINT_REAPPEARANCE_FRAMES = 12;
116	
117	/**
118	 * One move. Frame counts are 60 Hz frames: `startup` frames come before the first active frame, then `active`, then
119	 * `recovery`. Distances and velocities are sub-pixels (per frame). A move that does not strike with its hitbox
120	 * (`effect` other than `strike`) keeps a hitbox for drawing, but its own damage, stun and pushback are 0.
121	 */
122	export const duelMoveSchema = z
123	  .strictObject({
124	    timing: duelMoveTimingSchema,
125	    kind: z.enum(["strike", "throw"]),
126	    effect: moveEffectSchema,
127	    /** Decides what blocking it costs (§7) and which rules apply. */
128	    category: moveCategorySchema,
129	    /** The hurtbox the attacker uses while performing the move. */
130	    stance: z.enum(["standing", "crouching"]),
131	    guard: guardLevelSchema,
132	    /** One box for the whole active phase. */
133	    hitbox: boxSchema,
134	    /** Before combo scaling. */
135	    damage: count,
136	    /** Frames the defender cannot act after a hit, counting the contact frame; for a throw, the knockdown after it. */
137	    hitstun: count,
138	    /** Frames the defender cannot act after blocking, counting the contact frame; 0 for a throw. */
139	    blockstun: count,
140	    hitPushback: count,
141	    blockPushback: count,
142	    /** Upward velocity given to the defender on hit (sub-pixels per frame); 0 leaves a grounded defender grounded. */
143	    launch: count,
144	    /** Forward velocity of the attacker during startup and active frames. */
145	    advance: count,
146	    /** Frames from the move's first frame during which strikes (bolts included) pass through the attacker. */
147	    strikeInvulnerable: count,
148	    /** Stamina the defender spends to block it. */
149	    guardStaminaCost: count,
150	    /** Exactly when `effect` is `projectile`. */
151	    projectile: duelProjectileSchema.optional(),
152	    /** Exactly when `effect` is `zone`. */
153	    zone: duelZoneSchema.optional(),
154	    /** Only on a `feint`. */
155	    cancel: duelCancelSchema.optional(),
156	  })
157	  .superRefine((move, ctx) => {
158	    const { timing } = move;
159	    const isThrow = move.kind === "throw";
160	    if (isThrow !== (move.category === "throw") || isThrow !== (move.guard === "unguardable")) {
161	      ctx.addIssue({ code: "custom", path: ["kind"], message: "a throw, and only a throw, has the throw category and is unguardable" });
162	    }
163	    if ((move.effect === "projectile") !== (move.projectile !== undefined)) {
164	      ctx.addIssue({ code: "custom", path: ["projectile"], message: "a projectile move, and only a projectile move, has projectile data" });
165	    }
166	    if ((move.effect === "zone") !== (move.zone !== undefined)) {
167	      ctx.addIssue({ code: "custom", path: ["zone"], message: "a zone move, and only a zone move, has zone data" });
168	    }
169	    if (move.cancel !== undefined && move.effect !== "feint") {
170	      ctx.addIssue({ code: "custom", path: ["cancel"], message: "only a feint can be cancelled" });
171	    }
172	    if (move.damage === 0 && move.effect === "strike") ctx.addIssue({ code: "custom", path: ["damage"], message: "a strike deals damage" });
173	    if (move.hitstun === 0 && move.effect === "strike") ctx.addIssue({ code: "custom", path: ["hitstun"], message: "a strike has hitstun" });
174	    if (move.effect !== "strike") {
175	      // It never connects: nothing of its own to deal, and nothing to block.
176	      if (isThrow) ctx.addIssue({ code: "custom", path: ["effect"], message: "a throw strikes with its hitbox" });
177	      for (const field of ["damage", "hitstun", "blockstun", "hitPushback", "blockPushback", "launch", "guardStaminaCost"] as const) {
178	        if (move[field] !== 0) ctx.addIssue({ code: "custom", path: [field], message: `a ${move.effect} move never strikes, so its ${field} is 0` });
179	      }
180	      if (timing.onBlock.kind !== "spacing-dependent") {
181	        ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a move that never strikes is spacing-dependent on block" });
182	      }
183	    } else if (isThrow) {
184	      if (timing.onBlock.kind !== "unguardable") ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a throw is unguardable" });
185	      if (move.blockstun !== 0) ctx.addIssue({ code: "custom", path: ["blockstun"], message: "a throw cannot be blocked" });
186	    } else if (timing.onBlock.kind !== "frames") {
187	      ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a strike needs a frame advantage on block" });
188	    } else if (move.blockstun !== timing.active + timing.recovery + timing.onBlock.advantage) {
189	      // Contact on the first active frame, which is also the defender's first blockstun frame.
190	      ctx.addIssue({
191	        code: "custom",
192	        path: ["blockstun"],
193	        message: `blockstun ${move.blockstun} does not give ${timing.onBlock.advantage} on block (needs ${timing.active + timing.recovery + timing.onBlock.advantage})`,
194	      });
195	    }
196	    if (move.strikeInvulnerable > timing.startup) {
197	      ctx.addIssue({ code: "custom", path: ["strikeInvulnerable"], message: "strike invulnerability cannot outlast startup" });
198	    }
199	    if (move.effect === "feint") {
200	      if (timing.recovery < FEINT_REAPPEARANCE_FRAMES) {
201	        ctx.addIssue({ code: "custom", path: ["timing", "recovery"], message: `a feint's recovery holds its ${FEINT_REAPPEARANCE_FRAMES} reappearance frames` });
202	      }
203	      const reappeared = timing.startup + timing.active + FEINT_REAPPEARANCE_FRAMES;
204	      if (move.cancel !== undefined && (move.cancel.opens <= reappeared || move.cancel.opens > reappeared - FEINT_REAPPEARANCE_FRAMES + timing.recovery)) {
205	        ctx.addIssue({ code: "custom", path: ["cancel", "opens"], message: `a feint's cancel opens after its reappearance (frame ${reappeared}) and within its recovery` });
206	      }
207	    }
208	  });
209	
210	export type DuelMove = z.infer<typeof duelMoveSchema>;
211	
212	/** The one striking rule: whether a move connects with its own hitbox (strikes and throws do; bolt casts, zones and feints never). */
213	export function strikesWithHitbox(move: DuelMove): boolean {
214	  return move.effect === "strike";
215	}
216	
217	const hurtboxesSchema = z.strictObject({ standing: boxSchema, crouching: boxSchema, airborne: boxSchema });
218	
219	/** A fighter's body and movement. Distances are sub-pixels, speeds sub-pixels per frame, durations frames. */
220	export const duelFighterSchema = z.strictObject({
221	  hurtboxes: hurtboxesSchema,
222	  /** Two fighters' pushboxes never overlap: centred on the origin, `halfWidth` either side, `height` tall. */
223	  pushbox: z.strictObject({ halfWidth: positive, height: positive }),
224	  walkForwardSpeed: positive,
225	  walkBackSpeed: positive,
226	  jumpVelocity: positive,
227	  jumpSpeedX: count,
228	  /** Subtracted from the vertical velocity every airborne frame. */
229	  gravity: positive,
230	  dashFrames: positive,
231	  dashSpeed: positive,
232	  backdashFrames: positive,
233	  backdashSpeed: positive,
234	  /** Recovery of both fighters after a throw escape or two throws breaking each other. */
235	  throwBreakFrames: positive,
236	  /** How far each fighter is pushed away from the other when a throw breaks. */
237	  throwBreakPushback: count,
238	});
239	
240	export type DuelFighter = z.infer<typeof duelFighterSchema>;
241	
242	/** The single-plane arena: a floor between two walls. */
243	export const duelArenaSchema = z.strictObject({
244	  subPixelsPerPixel: positive,
245	  /** Wall to wall, in sub-pixels. Fighters' origins stay a pushbox half-width inside the walls. */
246	  width: positive,
247	  /** Distance between the two fighters' origins at the start, placed symmetrically about the centre. */
248	  startGap: positive,
249	});
250	
251	export type DuelArena = z.infer<typeof duelArenaSchema>;
252	
253	/** §7's round, stamina and combo rules as numbers. */
254	export const duelRulesSchema = z.strictObject({
255	  roundFrames: positive,
256	  overtimeFrames: positive,
257	  maxHealth: positive,
258	  maxStamina: positive,
259	  dashStaminaCost: count,
260	  guardStaminaCost: z.strictObject({ light: count, heavy: count, special: count }),
261	  /** Frames without spending or blocking before stamina regenerates. */
262	  staminaRegenDelayFrames: count,
263	  /** After the delay, one stamina point every this many frames (3 frames is 20 a second). */
264	  staminaRegenIntervalFrames: positive,
265	  guardBreakStaggerFrames: positive,
266	  /** Added to the stamina a guard break leaves, up to `maxStamina`. */
267	  guardBreakStaminaRestore: count,
268	  /** Percent of base damage for the first, second, ... damaging hit of a combo. */
269	  comboScaling: z.array(z.int().min(1).max(100)).min(1).readonly(),
270	  /** The damaging hit that forces the non-juggleable recovery. */
271	  comboCap: positive,
272	  forcedRecoveryFrames: positive,
273	  throwEscapeFrames: positive,
274	  inputBufferFrames: positive,
275	  /**
276	   * The throw chord window: a light or heavy move that a free fighter started becomes the throw when the other button
277	   * is pressed up to this many frames later, before the move's first active frame (keyboard rollover, §8).
278	   */
279	  throwChordFrames: count,
280	});
281	
282	export type DuelRules = z.infer<typeof duelRulesSchema>;
283	
284	/** Which move each input starts (§8): down + heavy is the low sweep, forward + heavy the launcher, down + light the anti-air. */
285	export const duelCommandsSchema = z.strictObject({
286	  light: z.string(),
287	  downLight: z.string(),
288	  heavy: z.string(),
289	  downHeavy: z.string(),
290	  forwardHeavy: z.string(),
291	  special1: z.string(),
292	  special2: z.string(),
293	  throw: z.string(),
294	});
295	
296	export type DuelCommands = z.infer<typeof duelCommandsSchema>;
297	
298	/**
299	 * The commands a light or heavy press starts, each with the button that still turns it into the throw inside the
300	 * throw chord window.
301	 */
302	export const THROW_CHORD_PARTNER = {
303	  light: "heavy",
304	  downLight: "heavy",
305	  heavy: "light",
306	  downHeavy: "light",
307	  forwardHeavy: "light",
308	} as const satisfies Partial<Record<keyof DuelCommands, "light" | "heavy">>;
309	
310	/** A kit's two specials (§9): eating a fruit replaces them; normals, throw and guard stay the Duelist's. */
311	export const duelKitSchema = z.strictObject({ special1: z.string(), special2: z.string() });
312	export type DuelKit = z.infer<typeof duelKitSchema>;
313	
314	/** The fruitless Duelist and the first two fruits (§9's slice). */
315	export const KIT_IDS = ["duelist", "ember", "smoke"] as const;
316	export type KitId = (typeof KIT_IDS)[number];
317	
318	export const duelKitsSchema = z.strictObject({ duelist: duelKitSchema, ember: duelKitSchema, smoke: duelKitSchema });
319	export type DuelKits = z.infer<typeof duelKitsSchema>;
320	
321	/**
322	 * Everything the duel step reads. `movesetVersion` identifies it all, and a duel state records that version. `moves`
323	 * holds every kit's moves; `commands` are the Duelist's (its specials are `kits.duelist`'s), and a fighter's specials
324	 * come from its kit.
325	 */
326	export const duelMovesetSchema = z
327	  .strictObject({
328	    rules: duelRulesSchema,
329	    arena: duelArenaSchema,
330	    fighter: duelFighterSchema,
331	    moves: z.array(duelMoveSchema).min(1).readonly(),
332	    commands: duelCommandsSchema,
333	    kits: duelKitsSchema,
334	  })
335	  .superRefine((moveset, ctx) => {
336	    const { rules, arena, fighter } = moveset;
337	    const byId = new Map<string, DuelMove>();
338	    moveset.moves.forEach((move, index) => {
339	      const id = move.timing.id;
340	      if (byId.has(id)) ctx.addIssue({ code: "custom", path: ["moves", index, "timing", "id"], message: `${id}: duplicate move id` });
341	      byId.set(id, move);
342	      // A move named like a §8 baseline row must use that row's timing exactly.
343	      const baseline = baselineFrameBudgets.find((row) => row.id === id);
344	      if (baseline !== undefined && !sameTiming(move.timing, baseline)) {
345	        ctx.addIssue({ code: "custom", path: ["moves", index, "timing"], message: `${id}: timing differs from §8's baseline row` });
346	      }
347	      const cost = move.category === "throw" || !strikesWithHitbox(move) ? 0 : rules.guardStaminaCost[move.category];
348	      if (move.guardStaminaCost !== cost) {
349	        ctx.addIssue({ code: "custom", path: ["moves", index, "guardStaminaCost"], message: `${id}: blocking a ${move.category} costs ${cost}` });
350	      }
351	      const { projectile } = move;
352	      if (projectile !== undefined) {
353	        if (projectile.guardStaminaCost !== rules.guardStaminaCost.special) {
354	          ctx.addIssue({ code: "custom", path: ["moves", index, "projectile", "guardStaminaCost"], message: `${id}: blocking a special costs ${rules.guardStaminaCost.special}` });
355	        }
356	        // A bolt's id names it in events, so it must not name a move too (it is never a fighter's move).
357	        if (moveset.moves.some((other) => other.timing.id === projectile.id || (other !== move && other.projectile?.id === projectile.id))) {
358	          ctx.addIssue({ code: "custom", path: ["moves", index, "projectile", "id"], message: `${projectile.id}: a projectile id must be unique` });
359	        }
360	      }
361	    });
362	    for (const kitId of KIT_IDS) {
363	      for (const slot of ["special1", "special2"] as const) {
364	        const id = moveset.kits[kitId][slot];
365	        const move = byId.get(id);
366	        if (move === undefined) {
367	          ctx.addIssue({ code: "custom", path: ["kits", kitId, slot], message: `unknown move "${id}"` });
368	        } else if (move.category !== "special") {
369	          ctx.addIssue({ code: "custom", path: ["kits", kitId, slot], message: `"${id}" is not a special` });
370	        }
371	      }
372	    }
373	    for (const slot of ["special1", "special2"] as const) {
374	      if (moveset.commands[slot] !== moveset.kits.duelist[slot]) {
375	        ctx.addIssue({ code: "custom", path: ["commands", slot], message: `the ${slot} command is the Duelist kit's` });
376	      }
377	    }
378	    for (const [command, id] of Object.entries(moveset.commands)) {
379	      const move = byId.get(id);
380	      if (move === undefined) {
381	        ctx.addIssue({ code: "custom", path: ["commands", command], message: `unknown move "${id}"` });
382	      } else if ((command === "throw") !== (move.kind === "throw")) {
383	        ctx.addIssue({ code: "custom", path: ["commands", command], message: `"${id}" is the wrong kind of move for ${command}` });
384	      }
385	    }
386	    // The chord window closes before a light or heavy move could strike, so a throw never replaces an active hitbox.
387	    for (const command of Object.keys(THROW_CHORD_PARTNER) as (keyof typeof THROW_CHORD_PARTNER)[]) {
388	      const move = byId.get(moveset.commands[command]);
389	      if (move !== undefined && rules.throwChordFrames >= move.timing.startup) {
390	        ctx.addIssue({ code: "custom", path: ["rules", "throwChordFrames"], message: `the throw chord window outlasts ${move.timing.id}'s startup` });
391	      }
392	    }
393	    if (rules.comboCap > rules.comboScaling.length) {
394	      ctx.addIssue({ code: "custom", path: ["rules", "comboCap"], message: "every hit up to the cap needs a scaling step" });
395	    }
396	    if (rules.dashStaminaCost > rules.maxStamina) {
397	      ctx.addIssue({ code: "custom", path: ["rules", "dashStaminaCost"], message: "a dash would cost more than full stamina" });
398	    }
399	    // Symmetric start positions need even distances, and both fighters must start inside the walls and out of reach
400	    // of every move, including the distance an advancing move travels through its startup and active frames (§6: no
401	    // free opening hit).
402	    if (arena.width % 2 !== 0 || arena.startGap % 2 !== 0) {
403	      ctx.addIssue({ code: "custom", path: ["arena"], message: "arena width and start gap must be even" });
404	    }
405	    if (arena.startGap > arena.width - 2 * fighter.pushbox.halfWidth) {
406	      ctx.addIssue({ code: "custom", path: ["arena", "startGap"], message: "the start positions lie outside the walls" });
407	    }
408	    const hurtReach = Math.max(...Object.values(fighter.hurtboxes).map((box) => Math.max(box.x + box.w, -box.x)));
409	    const hitReach = Math.max(
410	      ...moveset.moves.filter(strikesWithHitbox).map((move) => move.hitbox.x + move.hitbox.w + move.advance * (move.timing.startup + move.timing.active)),
411	    );
412	    if (arena.startGap < hitReach + hurtReach) {
413	      ctx.addIssue({ code: "custom", path: ["arena", "startGap"], message: "fighters would start within reach of a move" });
414	    }
415	  });
416	
417	export type DuelMoveset = z.infer<typeof duelMovesetSchema>;
418	
419	function sameTiming(a: DuelMoveTiming, b: MoveTiming): boolean {
420	  const advantage = (timing: MoveTiming | DuelMoveTiming) => (timing.onBlock.kind === "frames" ? timing.onBlock.advantage : null);
421	  return (
422	    a.id === b.id &&
423	    a.name === b.name &&
424	    a.startup === b.startup &&
425	    a.active === b.active &&
426	    a.recovery === b.recovery &&
427	    a.onBlock.kind === b.onBlock.kind &&
428	    advantage(a) === advantage(b)
429	  );
430	}
431	
432	export function validateDuelMove(candidate: unknown): ValidationResult<DuelMove> {
433	  const parsed = duelMoveSchema.safeParse(candidate);
434	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
435	}
436	
437	export function validateDuelMoveset(candidate: unknown): ValidationResult<DuelMoveset> {
438	  const parsed = duelMovesetSchema.safeParse(candidate);
439	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
440	}
