194	function randomKitInputs(seed: number, frames: number): DuelInputs[] {
195	  let rng = seed;
196	  const draw = (bound: number) => {
197	    const drawn = nextInt(rng, bound);
198	    rng = drawn.state;
199	    return drawn.value;
200	  };
201	  const held = [0, 0];
202	  const left = [0, 0];
203	  const inputs: DuelInputs[] = [];
204	  for (let frame = 0; frame < frames; frame++) {
205	    for (const player of [0, 1] as const) {
206	      if (left[player] === 0) {
207	        const back = player === 0 ? I("left") : I("right");
208	        const forward = player === 0 ? I("right") : I("left");
209	        const moves = [0, back, back, back | I("down"), forward, forward, forward, I("down"), I("up"), I("up") | forward, I("up") | back, I("dash"), back | I("dash")];
210	        const attacks = [LIGHT, LIGHT, HEAVY, I("down", "heavy"), forward | HEAVY, I("down", "light"), U, U, SPECIAL2, SPECIAL2, I("light", "heavy")];
211	        const attack = draw(100) < 25;
212	        held[player] = attack ? attacks[draw(attacks.length)]! : moves[draw(moves.length)]!;
213	        left[player] = attack ? 1 + draw(2) : 1 + draw(20);
214	      }
215	      left[player]!--;
216	    }
217	    inputs.push([held[0]!, held[1]!]);
218	  }
219	  return inputs;
220	}
